namespace ConRoi.Gameplay.EditorChecks {
[InitializeOnLoad] public static class InvestigationFlowChecks {
 const string Key="ConRoi.InvestigationFlow20261109",Scene="Assets/ConRoi/Modules/Gameplay/Scenes/Gameplay_ThuNghiem.unity";
 [Serializable] class Row {public string name,detail;public bool pass;}
 [Serializable] class Report {public string source,kind="PLAYMODE_API_FIXTURE_NOT_UI",unity,scene;public int failures;public List<Row> checks=new List<Row>();}
 static Report report;static InvestigationSession s;
 static InvestigationFlowChecks(){EditorApplication.update+=Tick;}
 static string Arg(string k){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,k);return i>=0&&i+1<a.Length?a[i+1]:"";}
 public static void RunBatch(){if(Application.unityVersion!="6000.6.2f1"||!Application.isBatchMode||EditorApplication.isPlayingOrWillChangePlaymode)throw new InvalidOperationException("Need explicit batch Unity 6000.6.2f1");if(!Path.IsPathRooted(Arg("--flow-output"))||!Path.IsPathRooted(Arg("--investigation-save-dir"))||Directory.Exists(Arg("--investigation-save-dir")))throw new InvalidOperationException("New private profile required");Directory.CreateDirectory(Arg("--flow-output"));EditorSceneManager.OpenScene(Scene,OpenSceneMode.Single);SessionState.SetString(Key,"pending");EditorApplication.EnterPlaymode();}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;string phase=SessionState.GetString(Key,"");if(phase=="finished"&&!EditorApplication.isPlayingOrWillChangePlaymode){SessionState.SetString(Key,"");EditorApplication.Exit(SessionState.GetInt(Key+".exit",2));return;}if(phase!="pending"||!EditorApplication.isPlaying)return;SessionState.SetString(Key,"running");report=new Report{source=Arg("--flow-source"),unity=Application.unityVersion,scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path};GameObject root=null;try{s=TrialPlaybackContextChecks.BuildEnvironment(out root);if(Arg("--flow-suite")=="all"){Clip();Conclusions();Route();}else if(Arg("--flow-suite")=="conclusion")Conclusions();else Clip();}catch(Exception e){Check("fixture_exception",false,e.ToString());}finally{if(root)UnityEngine.Object.DestroyImmediate(root);File.WriteAllText(Path.Combine(Arg("--flow-output"),"results.json"),JsonUtility.ToJson(report,true));Debug.Log("InvestigationFlow checks="+report.checks.Count+" failures="+report.failures);SessionState.SetInt(Key+".exit",report.failures==0?0:1);SessionState.SetString(Key,"finished");EditorApplication.ExitPlaymode();}}
 static void Check(string name,bool pass,string detail=""){if(!pass&&detail==""&&s!=null)detail="Message="+s.Message+" page="+s.Page+" paused="+s.Paused+" confirmed="+(typeof(InvestigationSession).GetProperty("ConclusionsConfirmed")?.GetValue(s))+" data="+JsonUtility.ToJson(s.data);report.checks.Add(new Row{name=name,pass=pass,detail=detail});if(!pass)report.failures++;}
 static object Call(string name,params object[] args)=>typeof(InvestigationSession).GetMethod(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(s,args);
 static void Fresh(){s.ClosePage();s.SetPaused(false);s.data=new InvestigationSave{introAccepted=true};for(int i=0;i<4;i++)s.data.conclusions.Add(new ConclusionRecord());}
 static string Transcript(string id){var m=typeof(InvestigationSession).GetMethod("EvidenceTranscript");return m!=null?(string)m.Invoke(s,new object[]{id}):InvestigationContent.Get(id).transcript;}
 static void Clip(){
  bool baseline=Arg("--flow-baseline")=="yes";string secret=InvestigationContent.Get("clip").transcript;
  foreach(var flags in new[]{new[]{false,false},new[]{true,false},new[]{false,true},new[]{true,true}}){Fresh();s.Acquire("clip");s.data.clipBeforeSeen=flags[0];s.data.clipEventSeen=flags[1];bool ready=flags[0]&&flags[1];string label=flags[0]+"_"+flags[1];
   string data=JsonUtility.ToJson(s.data);Check(label+"_transcript_disclosure",ready?Transcript("clip")==secret:Transcript("clip")!=secret);Check(label+"_read_only",JsonUtility.ToJson(s.data)==data);
   if(baseline)continue;
   s.OpenEvidence("clip");Check(label+"_inspect_no_grant",s.Record("clip").observations.Count==0&&s.data.evidence.Count==1);s.OpenPage("compare");Check(label+"_compare_same_guard",ready?Transcript("clip")==secret:Transcript("clip")!=secret);
   Call("RecordVisibleObservations","clip");Check(label+"_batch_record_guard",s.Record("clip").observations.Count==(ready?3:0));Check(label+"_message_honest",ready?s.Message.StartsWith("Đã ghi"):!s.Message.StartsWith("Đã ghi"));Call("RecordVisibleObservations","clip");Check(label+"_repeat_unique",s.Record("clip").observations.Count==(ready?3:0));
   SaveVerified();string bytes=File.ReadAllText(s.SavePath);s.data.clipBeforeSeen=!flags[0];s.data.clipEventSeen=!flags[1];Check(label+"_load_roundtrip",s.Load()&&s.data.clipBeforeSeen==flags[0]&&s.data.clipEventSeen==flags[1]&&File.ReadAllText(s.SavePath)==bytes);Check(label+"_loaded_disclosure",ready?Transcript("clip")==secret:Transcript("clip")!=secret);
  }
  if(baseline)return;
  Fresh();Check("unacquired_empty",Transcript("clip")=="");s.Acquire("letter");Check("other_transcript_unchanged",Transcript("letter")==InvestigationContent.Get("letter").transcript);Check("missing_id_empty",Transcript("unknown")=="");
  Fresh();s.Acquire("clip");Call("RegisterClipExposure",.5f,1.2f);Check("before_only_no_event",s.data.clipBeforeSeen&&!s.data.clipEventSeen&&Transcript("clip")!=secret);s.ClosePage();s.OpenPage("dossier");Check("return_no_grant",s.Record("clip").observations.Count==0);Call("RegisterClipExposure",4f,4.9f);Check("real_windows_unlock",s.data.clipBeforeSeen&&s.data.clipEventSeen&&Transcript("clip")==secret);Call("RecordVisibleObservations","clip");SaveVerified();Check("continue_record_load",s.Load()&&s.Record("clip").observations.Count==3&&!s.Has("decoded")&&!s.data.finalized);
 }
 static void Route(){
  Fresh();Check("route_clean_start",s.data.evidence.Count==0&&!s.data.firstFloorRecorded&&!s.data.finalized);
  var target=new GameObject("API route interaction fixture");try{var item=target.AddComponent<InvestigationInteractable>();item.evidenceId="slide";s.Interact(item);Check("route_inspect_not_record",s.Has("slide")&&!s.data.firstFloorRecorded&&s.Record("slide").observations.Count==0);Call("RecordVisibleObservations","slide");s.Observe("slide",0);Check("route_record_unique_progress",s.data.firstFloorRecorded&&s.Record("slide").observations.Count==2);s.OpenPage("dossier");Check("route_note_review_phone_objective",s.data.firstNotesReviewed&&s.CurrentObjective.Contains("điện thoại"));item.evidenceId="phone";s.Interact(item);s.Acquire("clip");s.OpenPage("clip");Call("RegisterClipExposure",.5f,1.2f);Call("RegisterClipExposure",4f,4.9f);Call("RecordVisibleObservations","clip");Check("route_clip_recorded",s.Record("clip").observations.Count==3);
   item.evidenceId="mechanism";s.Interact(item);item.evidenceId="ha";s.Interact(item);Check("route_Ha_received_not_solved",s.data.visitedHa&&s.Has("letter")&&!s.Has("decoded"));s.OpenPage("cipher");s.RecordReading();Check("route_blank_cipher_no_leak",!s.Has("decoded"));s.Assign("T","Z");s.RecordReading();Check("route_wrong_partial_cipher_no_grant",!s.Has("decoded"));foreach(char c in InvestigationContent.Alphabet)s.Assign(c.ToString(),c.ToString());Check("route_cipher_reads_expected",s.ReadCipher().Replace(" • "," ")==InvestigationContent.HaPlain);s.RecordReading();s.RecordReading();Check("route_cipher_record_unique",s.Has("decoded")&&s.data.evidence.Count(e=>e.id=="decoded")==1&&!s.data.finalized);
   s.OpenPage("compare");s.AddRelation("letter","missing","note");s.AddRelation("letter","letter","note");s.AddRelation("letter","receipt"," ");Check("route_compare_invalid_not_recorded",s.data.relations.Count==0);s.AddRelation("letter","receipt"," Cần đối chiếu nguồn ");Check("route_compare_records_thought_not_verdict",s.data.relations.Count==1&&s.data.relations[0].note=="Cần đối chiếu nguồn"&&!s.data.finalized);
   item.action="table";s.Interact(item);s.StartTrial("release");s.AdvanceTrial(s.TrialDuration);s.AdvanceTrial(0);Check("route_trial_single_record",s.data.trials.Count==1&&!s.TrialRunning);s.OpenPage("conclusions");s.data.conclusions[0].grounds.Add("slide");s.SetConclusionConfirmation(true);Check("route_finalize_pending_choice",s.TryFinalizeConclusions()&&s.data.finalized&&s.data.conclusions.All(c=>c.choice==0));Check("route_load_preserves_all",s.Load()&&s.Has("decoded")&&s.data.relations.Count==1&&s.data.trials.Count==1&&s.data.finalized&&!s.TrialRunning);
   string state=JsonUtility.ToJson(s.data);byte[] finalBytes=File.ReadAllBytes(s.SavePath),pendingBytes=File.ReadAllBytes(Checkpoint);try{File.WriteAllText(Checkpoint,File.ReadAllText(Checkpoint).Replace("\"evidence\": [","\"evidence\": null, \"notEvidence\": ["));Check("checkpoint_malformed_rejected",!s.LoadConclusionCheckpoint()&&JsonUtility.ToJson(s.data)==state&&finalBytes.SequenceEqual(File.ReadAllBytes(s.SavePath)));}finally{File.WriteAllBytes(Checkpoint,pendingBytes);}Check("route_explicit_checkpoint_load",s.LoadConclusionCheckpoint()&&!s.data.finalized&&s.data.relations.Count==1&&s.data.trials.Count==1);SaveVerified();Check("route_continue_save_load",s.Load()&&!s.data.finalized&&s.Observation("clip",2)&&s.data.conclusions[0].grounds.Contains("slide"));
  }finally{UnityEngine.Object.DestroyImmediate(target);}
 }
 static void SaveVerified(){s.Save();if(!s.Message.StartsWith("Đã lưu"))throw new IOException("Fixture prerequisite failed before Load: "+s.Message);}
 static string Checkpoint=>Path.Combine(Path.GetDirectoryName(s.SavePath),"prototype.before-conclusion.json");
 static void Confirm(bool value){var m=typeof(InvestigationSession).GetMethod("SetConclusionConfirmation");if(m!=null)m.Invoke(s,new object[]{value});else typeof(InvestigationSession).GetField("confirmConclusion",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(s,value);}
 static bool Confirmed {get {var p=typeof(InvestigationSession).GetProperty("ConclusionsConfirmed");return p!=null?(bool)p.GetValue(s):(bool)typeof(InvestigationSession).GetField("confirmConclusion",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(s);}}
 static bool FinalizeRecord(){var m=typeof(InvestigationSession).GetMethod("TryFinalizeConclusions");if(m!=null)return (bool)m.Invoke(s,null);/* Baseline API reproduction of the exact existing button handler, not UI input. */s.data.finalized=true;s.Save();return true;}
 static void Draft(){Fresh();s.Acquire("slide");s.Observe("slide",0);s.OpenPage("conclusions");s.data.conclusions[0].claim="Cần kiểm thêm";s.data.conclusions[0].grounds.Add("slide");}
 static void Conclusions(){
  bool baseline=Arg("--flow-baseline")=="yes";Draft();SaveVerified();byte[] good=File.ReadAllBytes(s.SavePath);Confirm(true);bool result;
  using(var held=new FileStream(s.SavePath,FileMode.Open,FileAccess.Read,FileShare.None)){result=FinalizeRecord();}
  Check("target_failure_returns_false",!result);Check("target_failure_not_finalized",!s.data.finalized);Check("target_failure_old_bytes_preserved",good.SequenceEqual(File.ReadAllBytes(s.SavePath)));Check("precommit_checkpoint_exists",File.Exists(Checkpoint));Check("old_valid_save_loads_after_failure",s.Load()&&s.Observation("slide",0)&&!s.data.finalized);Check("load_clears_confirmation",!Confirmed);
  if(baseline)return;
  Confirm(true);Check("recovery_commit_succeeds",FinalizeRecord()&&s.data.finalized&&s.Message.StartsWith("Đã lưu"));var pre=JsonUtility.FromJson<InvestigationSave>(File.ReadAllText(Checkpoint));var committed=JsonUtility.FromJson<InvestigationSave>(File.ReadAllText(s.SavePath));
  Check("checkpoint_schema_and_pending",pre.schema==1&&pre.namespaceId==s.data.namespaceId&&!pre.finalized&&pre.conclusions[0].claim==s.data.conclusions[0].claim&&pre.conclusions[0].grounds.SequenceEqual(new[]{"slide"}));Check("final_save_committed",committed.finalized&&committed.evidence.Count==1);Check("final_load_preserves_record",s.Load()&&s.data.finalized&&s.data.conclusions[0].grounds.Contains("slide")&&!Confirmed);
  Draft();SaveVerified();good=File.ReadAllBytes(s.SavePath);Confirm(true);string block=Checkpoint+".tmp";Directory.CreateDirectory(block);try{result=FinalizeRecord();Check("checkpoint_create_failure_rejected",!result&&!s.data.finalized&&good.SequenceEqual(File.ReadAllBytes(s.SavePath)));}finally{Directory.Move(block,Path.Combine(Arg("--flow-output"),"blocked-temp-directory-preserved"));}
  Check("checkpoint_recovery",FinalizeRecord()&&s.data.finalized);Check("checkpoint_failure_valid_load",s.Load());
  Draft();SaveVerified();good=File.ReadAllBytes(s.SavePath);Confirm(true);using(var held=new FileStream(Checkpoint,FileMode.Open,FileAccess.Read,FileShare.None)){result=FinalizeRecord();}Check("checkpoint_replace_failure_rejected",!result&&!s.data.finalized&&good.SequenceEqual(File.ReadAllBytes(s.SavePath)));Check("checkpoint_replace_recovery",FinalizeRecord());
  Draft();Confirm(false);string before=JsonUtility.ToJson(s.data);good=File.ReadAllBytes(s.SavePath);Check("unconfirmed_rejected",!FinalizeRecord()&&JsonUtility.ToJson(s.data)==before&&good.SequenceEqual(File.ReadAllBytes(s.SavePath)));
  Confirm(true);s.data.conclusions[1].claim="Điều vừa sửa";Check("edit_invalidates_signature",!Confirmed&&!FinalizeRecord());Confirm(true);s.ClosePage();s.OpenPage("conclusions");Check("return_requires_confirmation",!Confirmed&&!FinalizeRecord());Confirm(true);s.SetPaused(true);Check("pause_clears_confirmation",!Confirmed&&!FinalizeRecord());s.SetPaused(false);Confirm(true);Check("resume_can_confirm_and_commit",FinalizeRecord());
  // No verdict grading: all four unset choices remain valid prototype records.
  Draft();s.data.conclusions[0].grounds.Clear();s.data.conclusions[0].claim="";Confirm(true);Check("not_enough_is_allowed",FinalizeRecord()&&s.data.finalized&&s.data.conclusions.All(c=>c.choice==0));Check("no_auto_grants_or_trials",s.data.evidence.Count==1&&!s.Has("decoded")&&s.data.trials.Count==0);Check("pending_checkpoint_not_autoloaded",s.Load()&&s.data.finalized);
  // Explicit checkpoint restore, private file only: same schema, no automatic backup selection.
  Check("explicit_pending_restore",(bool)Call("LoadConclusionCheckpoint")&&!s.data.finalized&&s.data.conclusions.All(c=>c.choice==0));s.Observe("slide",1);SaveVerified();Check("continue_after_restore",s.Load()&&s.Record("slide").observations.Count==2);
 }
}}
